insert into criterion_pairs (pair_key,slot,self_key,pref_key,category,cluster,grp,match_type,is_absolute,mapping_validated)
select s.pair_key,(row_number() over (order by s.ord)-1)::smallint,s.key,r.key,s.category,s.cluster,
  (case s.category when 'PHYSIQUE' then 'physique' when 'MODE VIE' then 'mode_vie' else 'valeurs' end)::score_group,
  t.mt::match_type, s.cluster like '%FILTRE%', t.val
from criteria s
join criteria r on r.pair_key=s.pair_key and r.direction='pref'
join (values (array['genre','phys_silhouette','phys_poitrine','vis_forme','vis_machoire','vis_menton','vis_pommettes','vis_front','vis_nez','vis_levres','vis_dents_align','vis_dents_blanches','vis_fossettes','vis_traits','yeux_couleur','yeux_forme','yeux_cils','yeux_lunettes','chev_longueur','chev_couleur','chev_forme','chev_volume','pil_barbe','pil_corps','pil_sourcils','peau_couleur','peau_bronzage','peau_rousseur','peau_grains_beaute','style_vetement','style_piercings','style_maquillage','style_parfum','life_sommeil','life_energie','life_objets','voyage_paysage','soc_reseau','com_patienc','db_sex_or'],'aligne',true),(array['val_religion'],'echelle',false),(array['phys_taille','phys_poids','vis_symetrie','vis_sourire','pil_moustache','peau_acne','style_tatouages','life_horaires','life_orga','life_cuisine','life_proprete','life_manuel','life_job','loisir_num','loisir_cult','loisir_amis','loisir_arts','loisir_passion','loisir_benev','voyage_aime','voyage_style','voyage_prepa','voyage_transp','voyage_expat','sport_solo','sport_groupe','sport_eau','sport_freq','soc_extra','soc_intro','soc_famille','soc_amis','fin_vision','mob_transp','animaux','vice_conso','com_integ','com_drague','com_ecoute','com_emot','com_humour','com_canal','com_conflit','com_franchis','com_empathie','psy_confianc','psy_anxiete','psy_vision','psy_curiosit','psy_creativ','psy_rigueur','psy_competit','psy_action','psy_risque','psy_ambition','psy_humilite','psy_control','psy_adaptab','psy_spontan','psy_discipli','psy_persever','psy_respons','val_but','val_fidelite','val_honnete','val_spirit','val_politique','val_ecolo','val_tradition','val_culture','val_etudes','val_morale','db_relation','db_mariage','db_enfants','cpl_dynamiq','cpl_fusion','cpl_affect','cpl_espace','cpl_jalous','proj_prio','proj_statut','proj_lieu','proj_ancrage','proj_retraite','proj_rythme','db_regime'],'mapping',false),(array['peau_cicatrices','peau_rides','life_ecrans','fin_comport','com_critiq'],'repoussoir',false)) t(keys,mt,val) on s.pair_key = any(t.keys)
where s.direction='self';;
